-- Ejecutar este script completo en el SQL Editor de Supabase
-- (Project > SQL Editor > New query > pegar > Run)
--
-- Bibliografía anatómica: resúmenes escritos con conocimiento general de
-- anatomía (no copiados textualmente de ningún libro), citando qué texto
-- clásico de la carrera cubre cada tema. 6 fichas regionales (hombro, codo,
-- antebrazo, muñeca, mano, plexo braquial) + 3 fichas de sistema completo
-- (inervación, irrigación, sistema articular) del Miembro Superior.
--
-- Este archivo es un volcado completo y reproducible del estado actual de
-- la tabla (generado con pg_dump --data-only --column-inserts). Para
-- recrearla desde cero, correr todo el archivo tal cual.

create table if not exists public.bibliography_topics (
  id bigint generated by default as identity primary key,
  title text not null,
  region text not null,
  summary text,
  bones text[] default '{}',
  ligaments text[] default '{}',
  muscles text[] default '{}',
  nerves text[] default '{}',
  vessels text[] default '{}',
  movements text[] default '{}',
  clinical_relevance text[] default '{}',
  sources text[] default '{}',
  created_at timestamptz default now()
);

alter table public.bibliography_topics enable row level security;

do $$
begin
  if not exists (
    select 1 from pg_policies
    where tablename = 'bibliography_topics' and policyname = 'Public read access'
  ) then
    create policy "Public read access"
      on public.bibliography_topics
      for select
      to anon, authenticated
      using (true);
  end if;
end $$;

-- Datos (borra todo y vuelve a insertar, para que el script sea re-ejecutable)
truncate table public.bibliography_topics restart identity;





-- Data for Name: bibliography_topics; Type: TABLE DATA; Schema: public; Owner: -

INSERT INTO public.bibliography_topics (id, title, region, summary, bones, ligaments, muscles, nerves, movements, clinical_relevance, sources, created_at, vessels) VALUES (1, 'Complejo Articular del Hombro', 'Miembro Superior', 'La articulación más móvil del cuerpo, resultado de la acción coordinada de cuatro articulaciones (glenohumeral, acromioclavicular, esternoclavicular y escapulotorácica) que priorizan el rango de movimiento a costa de la estabilidad.', '{"Húmero (cabeza humeral)","Escápula (cavidad glenoidea, acromion, apófisis coracoides, espina escapular)",Clavícula}', '{"Ligamentos glenohumerales superior, medio e inferior","Ligamento coracohumeral","Ligamento coracoacromial","Ligamento acromioclavicular","Ligamentos coracoclaviculares (conoide y trapezoide)","Ligamentos esternoclaviculares"}', '{"Deltoides — abducción (porción media), flexión (anterior), extensión (posterior) de hombro — nervio axilar (C5-C6)","Supraespinoso — inicia/asiste la abducción y estabiliza la cabeza humeral — nervio supraescapular (C5-C6)","Infraespinoso — rotación externa — nervio supraescapular (C5-C6)","Redondo menor — rotación externa — nervio axilar (C5-C6)","Subescapular — rotación interna, estabiliza anteriormente — nervio subescapular (C5-C6)","Trapecio — eleva, retrae y rota la escápula — nervio accesorio espinal (XI par craneal)","Serrato anterior — protracción y rotación ascendente de la escápula — nervio torácico largo (C5-C7)","Dorsal ancho — extensión, aducción y rotación interna — nervio toracodorsal (C6-C8)","Pectoral mayor — aducción y rotación interna — nervios pectorales medial y lateral (C5-T1)"}', '{}', '{"Flexión: 0-180°","Extensión: 0-60°","Abducción: 0-180°","Rotación interna: 0-70°","Rotación externa: 0-90°","Ritmo escapulohumeral aproximado de 2:1 entre movimiento glenohumeral y escapulotorácico durante la elevación"}', '{"Síndrome de pinzamiento subacromial: compresión de los tendones del manguito rotador (sobre todo supraespinoso) contra el arco coracoacromial","Rotura del manguito rotador: más frecuente en el tendón del supraespinoso, cerca de su inserción en el troquíter","Capsulitis adhesiva (hombro congelado): pérdida progresiva y dolorosa del rango activo y pasivo","Inestabilidad glenohumeral: predominantemente anterior, dada la escasa congruencia ósea de la articulación","Tendinopatía del bíceps (porción larga): dolor en la corredera bicipital, frecuentemente asociada a patología del manguito rotador"}', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)","Gray''s Anatomy for Students","Cael - Anatomía Funcional","Tortora & Derrickson - Principios de Anatomía y Fisiología (13ª ed.)"}', '2026-08-16 00:00:01.518615+00', '{}');
INSERT INTO public.bibliography_topics (id, title, region, summary, bones, ligaments, muscles, nerves, movements, clinical_relevance, sources, created_at, vessels) VALUES (2, 'Articulación del Codo', 'Miembro Superior', 'Articulación compuesta (húmero-cubital, húmero-radial y radiocubital proximal) que combina flexo-extensión con la pronosupinación del antebrazo, con gran estabilidad ósea y ligamentaria.', '{"Húmero (tróclea, cóndilo, epicóndilo medial y lateral)","Cúbito/ulna (olécranon, apófisis coronoides, escotadura troclear)","Radio (cabeza radial, cuello)"}', '{"Ligamento colateral cubital (medial)","Ligamento colateral radial (lateral)","Ligamento anular del radio"}', '{"Bíceps braquial — flexión de codo y supinación del antebrazo — nervio musculocutáneo (C5-C6)","Braquial anterior — principal flexor del codo — nervio musculocutáneo (C5-C6)","Braquiorradial — flexor accesorio, más activo en posición neutra — nervio radial (C5-C6)","Tríceps braquial — extensión del codo — nervio radial (C6-C8)","Ancóneo — asiste la extensión y estabiliza la articulación — nervio radial (C7-C8, T1)","Pronador redondo — origen en el epicóndilo medial, pronación del antebrazo — nervio mediano (C6-C7)","Supinador — supinación del antebrazo — nervio radial/interóseo posterior (C5-C6)"}', '{}', '{"Flexión: 0-150°","Extensión: 0° (hiperextensión fisiológica leve en algunos individuos)","Ángulo de carga (valgo fisiológico) en extensión completa: aproximadamente 10-15°"}', '{"Epicondilitis lateral (\"codo de tenista\"): tendinopatía de los extensores de muñeca en su origen, principalmente el extensor radial corto del carpo","Epicondilitis medial (\"codo de golfista\"): tendinopatía de los flexores-pronadores en el epicóndilo medial","Neuropatía cubital en el codo (túnel cubital): el nervio cubital es superficial y vulnerable al pasar posterior al epicóndilo medial","Bursitis olecraneana: inflamación de la bolsa serosa superficial al olécranon","Fractura de cabeza radial: lesión frecuente por caída con el brazo en extensión"}', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)","Rouvière - Anatomía Humana","Gray''s Anatomy for Students"}', '2026-08-16 00:00:01.518615+00', '{}');
INSERT INTO public.bibliography_topics (id, title, region, summary, bones, ligaments, muscles, nerves, movements, clinical_relevance, sources, created_at, vessels) VALUES (3, 'Antebrazo y Articulación Radiocubital', 'Miembro Superior', 'El antebrazo permite la pronosupinación gracias a la rotación del radio alrededor del cúbito, coordinada entre las articulaciones radiocubital proximal y distal y conectada por la membrana interósea.', '{Radio,Cúbito/Ulna,"Membrana interósea antebraquial"}', '{"Ligamento anular del radio (radiocubital proximal)","Complejo del fibrocartílago triangular (radiocubital distal)","Membrana interósea (conecta radio y cúbito, transmite carga)"}', '{"Pronador redondo y pronador cuadrado — pronación — nervio mediano (C6-C7 y C8-T1 respectivamente)","Supinador y bíceps braquial — supinación — nervio radial y nervio musculocutáneo respectivamente"}', '{}', '{"Pronación: 0-80°","Supinación: 0-80°","Eje de rotación desde la cabeza radial hasta la cabeza cubital (cúpula del cúbito)"}', '{"Fractura de Monteggia: fractura de cúbito proximal con luxación de la cabeza radial","Fractura de Galeazzi: fractura de radio distal con luxación de la articulación radiocubital distal","Lesiones del fibrocartílago triangular: causa frecuente de dolor cubital de muñeca, especialmente en deportes de carga axial","Sinostosis radiocubital congénita: limita severamente la pronosupinación"}', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)","Rouvière - Anatomía Humana"}', '2026-08-16 00:00:01.518615+00', '{}');
INSERT INTO public.bibliography_topics (id, title, region, summary, bones, ligaments, muscles, nerves, movements, clinical_relevance, sources, created_at, vessels) VALUES (4, 'Muñeca (Radiocarpiana y Carpo)', 'Miembro Superior', 'Complejo articular formado por el radio distal, el fibrocartílago triangular y las dos hileras de huesos del carpo, fundamental para orientar la mano en el espacio.', '{"Radio distal","Hilera proximal del carpo: escafoides, semilunar, piramidal, pisiforme","Hilera distal del carpo: trapecio, trapezoide, grande (capitate), ganchoso"}', '{"Ligamento radiocarpiano dorsal y palmar","Ligamento colateral radial del carpo","Ligamento colateral cubital del carpo","Ligamentos intercarpianos (interóseos)","Retináculo flexor (techo del túnel carpiano)"}', '{"Flexor radial del carpo — flexión de muñeca — nervio mediano","Flexor cubital del carpo — flexión de muñeca — nervio cubital","Extensor radial largo y corto del carpo — extensión de muñeca — nervio radial","Extensor cubital del carpo — extensión de muñeca — nervio radial","Palmar largo — tensor de la aponeurosis palmar (ausente hasta en ~15% de la población) — nervio mediano"}', '{}', '{"Flexión: 0-80°","Extensión: 0-70°","Desviación radial: 0-20°","Desviación cubital: 0-30°"}', '{"Síndrome del túnel carpiano: compresión del nervio mediano bajo el retináculo flexor; la neuropatía compresiva más frecuente del miembro superior","Fractura de escafoides: alto riesgo de necrosis avascular por su vascularización retrógrada, con frecuencia subdiagnosticada tras una caída con la mano extendida","Inestabilidad escafolunar: lesión ligamentaria que puede evolucionar a un patrón de colapso conocido como SLAC (scapholunate advanced collapse)","Tenosinovitis de De Quervain: inflamación del primer compartimento extensor (abductor largo y extensor corto del pulgar)"}', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)","Kaplan Anatomy Lecture Notes","Gray''s Anatomy for Students"}', '2026-08-16 00:00:01.518615+00', '{}');
INSERT INTO public.bibliography_topics (id, title, region, summary, bones, ligaments, muscles, nerves, movements, clinical_relevance, sources, created_at, vessels) VALUES (5, 'Mano: Articulaciones y Arcos', 'Miembro Superior', 'Estructura altamente especializada, organizada en arcos óseos (longitudinal, transverso proximal y transverso distal) que permiten adaptarse a la prensión de objetos de formas muy diversas.', '{"Metacarpianos (I a V)","Falanges proximales, medias y distales","Sesamoideos del pulgar"}', '{"Ligamentos colaterales de las articulaciones metacarpofalángicas e interfalángicas","Ligamento colateral cubital de la metacarpofalángica del pulgar (lesión del esquiador/guardabosque)","Placas volares"}', '{"Interóseos dorsales — abducción de los dedos — nervio cubital","Interóseos palmares — aducción de los dedos — nervio cubital","Lumbricales — flexión metacarpofalángica con extensión interfalángica — nervio mediano (1º y 2º) y cubital (3º y 4º)","Músculos tenares (abductor corto, flexor corto, oponente del pulgar) — movimientos del pulgar — nervio mediano","Músculos hipotenares (abductor, flexor corto, oponente del meñique) — movimientos del 5º dedo — nervio cubital","Flexor superficial y profundo de los dedos — flexión de falanges — nervio mediano (y cubital para el 4º-5º dedo del flexor profundo)","Extensor de los dedos — extensión de falanges — nervio radial"}', '{}', '{"Flexión metacarpofalángica: 0-90°","Flexión interfalángica proximal: 0-100°","Flexión interfalángica distal: 0-80°","Oposición del pulgar: movimiento compuesto propio de la articulación trapeciometacarpiana (en silla de montar)"}', '{"Dedo en martillo (mallet finger): avulsión o rotura del tendón extensor en su inserción distal","Dedo en resorte (trigger finger): estenosis de la polea A1 que atrapa el tendón flexor","Contractura de Dupuytren: engrosamiento y retracción de la fascia palmar, más frecuente en 4º y 5º dedo","Rizartrosis: artrosis de la articulación trapeciometacarpiana del pulgar, muy frecuente y limitante para la pinza"}', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)","Rouvière - Anatomía Humana","McMinn - Gran Atlas de Anatomía"}', '2026-08-16 00:00:01.518615+00', '{}');
INSERT INTO public.bibliography_topics (id, title, region, summary, bones, ligaments, muscles, nerves, movements, clinical_relevance, sources, created_at, vessels) VALUES (6, 'Plexo Braquial', 'Miembro Superior', 'Red nerviosa formada por las ramas ventrales de C5 a T1, organizada en raíces, troncos, divisiones, fascículos y ramas terminales, que inerva la totalidad del miembro superior.', '{}', '{}', '{}', '{"Raíces: C5, C6, C7, C8, T1","Troncos: superior (C5-C6), medio (C7), inferior (C8-T1)","Divisiones: cada tronco se divide en una división anterior y una posterior","Fascículos: lateral, medial y posterior (nombrados según su relación con la arteria axilar)","Nervio musculocutáneo (fascículo lateral, C5-C7) — inerva los flexores del brazo (bíceps, braquial, coracobraquial)","Nervio mediano (fascículos lateral y medial, C6-T1) — inerva la mayoría de los flexores del antebrazo y los músculos tenares","Nervio cubital/ulnar (fascículo medial, C8-T1) — inerva flexor cubital del carpo, flexor profundo de los dedos (mitad cubital) y la mayoría de los músculos intrínsecos de la mano","Nervio radial (fascículo posterior, C5-T1) — inerva todos los extensores del brazo y antebrazo","Nervio axilar (fascículo posterior, C5-C6) — inerva deltoides y redondo menor","Nervio supraescapular (tronco superior, C5-C6) — inerva supraespinoso e infraespinoso","Nervio torácico largo (raíces C5-C7) — inerva serrato anterior; su lesión produce escápula alada"}', '{}', '{"Parálisis de Erb-Duchenne (C5-C6): lesión obstétrica o traumática alta; produce el clásico \"brazo del mesero\" (hombro en rotación interna, codo en extensión)","Parálisis de Klumpke (C8-T1): lesión baja del plexo, afecta principalmente la musculatura intrínseca de la mano","Lesiones por tracción (ej. accidentes con abducción forzada del brazo): pueden producir avulsiones radiculares con mal pronóstico de recuperación","La exploración sistemática de miotomas y dermatomas es clave para localizar el nivel de la lesión dentro del plexo"}', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)","Neuroanatomía Clínica, Snell (7ª ed.)","Fitzgerald - Neuroanatomía Clínica y Neurociencia"}', '2026-08-16 00:00:01.518615+00', '{}');
INSERT INTO public.bibliography_topics (id, title, region, summary, bones, ligaments, muscles, nerves, movements, clinical_relevance, sources, created_at, vessels) VALUES (7, 'Inervación del Miembro Superior', 'Miembro Superior', 'El plexo braquial (C5-T1) organiza toda la inervación motora y sensitiva del miembro superior en cinco nervios terminales principales, cada uno con un territorio y un patrón de lesión característico.', '{}', '{}', '{}', '{"Plexo Braquial (C5-T1): raíces → troncos (superior, medio, inferior) → divisiones → fascículos (lateral, medial, posterior) → nervios terminales.","Nervio Mediano: flexores del antebrazo, músculos tenares, sensibilidad palmar de los primeros 3½ dedos. Síndrome del túnel carpiano.","Nervio Cubital: flexor cubital del carpo, mayoría de los músculos intrínsecos de la mano. Neuropatía cubital en el codo.","Nervio Radial: todos los extensores del brazo y del antebrazo. Mano péndula en fracturas de la diáfisis humeral.","Nervio Musculocutáneo: flexores del brazo (bíceps braquial, braquial, coracobraquial).","Nervio Axilar: deltoides y redondo menor. Vulnerable en luxaciones anteriores de hombro.","Nervio Supraescapular: supraespinoso e infraespinoso.","Nervio Torácico Largo: serrato anterior; su lesión causa escápula alada.","Nervio Dorsal Escapular: elevador de la escápula y romboides.","Nervios Subescapulares (superior e inferior): subescapular y redondo mayor.","Nervios Pectorales (medial y lateral): pectoral mayor y pectoral menor."}', '{}', '{"La exploración sistemática de miotomas y dermatomas permite localizar el nivel de una lesión radicular o troncular","Las parálisis de Erb-Duchenne (C5-C6, lesión alta) y de Klumpke (C8-T1, lesión baja) representan los dos extremos del espectro de lesión del plexo braquial","El nervio radial es el más frecuentemente lesionado en fracturas de húmero; el axilar, en luxaciones de hombro; el cubital, en traumatismos del codo"}', '{"Neuroanatomía Clínica, Snell (7ª ed.)","Fitzgerald - Neuroanatomía Clínica y Neurociencia","Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)"}', '2026-08-16 17:09:48.207587+00', '{}');
INSERT INTO public.bibliography_topics (id, title, region, summary, bones, ligaments, muscles, nerves, movements, clinical_relevance, sources, created_at, vessels) VALUES (8, 'Irrigación del Miembro Superior', 'Miembro Superior', 'La sangre llega al miembro superior por un único eje arterial (subclavia → axilar → braquial → radial/cubital) que se ramifica progresivamente hasta la mano, mientras el retorno venoso combina un sistema superficial (visible, usado para accesos venosos) y uno profundo, que acompaña a las arterias.', '{}', '{}', '{}', '{}', '{}', '{"El pulso se palpa clásicamente en tres niveles: axilar, braquial (fosa cubital) y radial (muñeca)","El test de Allen evalúa la permeabilidad de ambos arcos palmares (radial y cubital) antes de una punción o cateterismo radial","La vena mediana cubital, en la fosa del codo, es el sitio más frecuente de venopunción por su calibre y accesibilidad","La red anastomótica periarticular del codo permite circulación colateral si se ocluye un segmento arterial localizado"}', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)","Rouvière - Anatomía Humana"}', '2026-08-16 17:09:48.250118+00', '{"Arteria Subclavia → Axilar → Braquial: eje arterial principal, cambia de nombre en cada punto de referencia anatómico (1ª costilla, borde del redondo mayor).","Arteria Axilar: irriga la cintura escapular a través de las ramas torácica superior, toracoacromial, torácica lateral, subescapular y circunflejas humerales.","Arteria Braquial: da la arteria profunda del brazo y las colaterales cubitales; se divide en radial y cubital en la fosa cubital.","Arteria Radial: superficial en el antebrazo, cruza la tabaquera anatómica; forma el arco palmar profundo.","Arteria Cubital: de mayor calibre, da la interósea común; forma el arco palmar superficial.","Arcos palmares (superficial y profundo): doble irrigación anastomótica de la mano, origen de las arterias digitales.","Venas superficiales (cefálica, basílica, mediana cubital): subcutáneas, visibles, sitio habitual de venopunción.","Venas profundas (radiales, cubitales, braquiales, axilar, subclavia): acompañan a las arterias homónimas hacia el tronco venoso braquiocefálico."}');
INSERT INTO public.bibliography_topics (id, title, region, summary, bones, ligaments, muscles, nerves, movements, clinical_relevance, sources, created_at, vessels) VALUES (9, 'Sistema Articular y Ligamentario del Miembro Superior', 'Miembro Superior', 'Desde el tronco hasta los dedos, el miembro superior encadena articulaciones con perfiles muy distintos: la esternoclavicular (única unión verdadera con el esqueleto axial), el hombro (máxima movilidad, mínima congruencia ósea), el codo y la muñeca (compromiso entre movilidad y estabilidad) y una red compleja de articulaciones carpianas y digitales que dan a la mano su destreza característica.', '{}', '{"Esternoclavicular: única articulación verdadera con el esqueleto axial, estabilizada por un disco articular y ligamentos esterno/interclaviculares y costoclavicular.","Acromioclavicular: estabilizada por los ligamentos acromioclavicular (horizontal) y coracoclavicular (vertical, conoide y trapezoide).","Glenohumeral (hombro): cápsula, rodete glenoideo y ligamentos glenohumerales superior/medio/inferior, reforzados por el manguito rotador.","Codo: cápsula común con ligamentos colaterales radial y cubital, y ligamento anular que permite la rotación de la cabeza del radio.","Radiocubital distal y complejo del fibrocartílago triangular: estabilidad entre cúbito, radio y carpo.","Radiocarpiana (muñeca): red de ligamentos radiocarpianos y ulnocarpianos, con el ligamento radioescafocapitate como \"cabestrillo\" del escafoides.","Intercarpianas: ligamentos interóseos cortos; el escafolunar es el de mayor relevancia clínica.","Metacarpofalángicas e interfalángicas: ligamentos colaterales y placas volares que estabilizan cada articulación digital.","Poleas anulares y cruciformes de los dedos: mantienen los tendones flexores aplicados al hueso durante la flexión."}', '{}', '{}', '{}', '{"La estabilidad del hombro depende casi enteramente de partes blandas (cápsula, rodete, ligamentos, manguito rotador), lo que explica por qué es la articulación que más se luxa del cuerpo","El ligamento escafolunar es la estructura clave en la estabilidad del carpo; su lesión no tratada puede evolucionar a un patrón de colapso (SLAC)","Las poleas anulares de los dedos (A1-A5) mantienen los tendones flexores aplicados al hueso; su lesión o engrosamiento produce el dedo en resorte","El complejo del fibrocartílago triangular es la causa más frecuente de dolor cubital de muñeca no traumático"}', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)","Kaplan Anatomy Lecture Notes","Gray''s Anatomy for Students"}', '2026-08-16 17:09:48.285109+00', '{}');



SELECT pg_catalog.setval('public.bibliography_topics_id_seq', 9, true);





SELECT pg_catalog.setval('public.bibliography_topics_id_seq', (select max(id) from public.bibliography_topics));
